raw:
{
  "spells": [
    {
      "id": "spell_light_10",
      "theory": "斑痕追照把魔力送入树脂媒介，使其化为一层极薄的探光，沿物体表面爬行。探光遇到近期留下的浅表污痕——如手印、泥渍或油迹——会被局部吸收，从而在施术者眼中显出暗色轮廓。它只照出污痕的形状与位置，不分析成分，也不回溯留下污痕的动作或人物。",
      "casting": "取一小块树脂在掌心搓热，用拇指压成薄片，再以食指沿薄片边缘画半圆，同时低声念出目标表面的方位。树脂变凉前将薄片举向待查区域。",
      "failure": "树脂未能完全软化时，探光会停在薄片内，只映出施术者自己的指纹。若目标表面太湿，污痕轮廓会晕开成一片模糊暗斑，无法分辨形状，且树脂会碎成数片。",
      "counters": [
        "用湿布擦过目标表面，污痕被抹去后探光无物可附。",
        "以强风直吹树脂薄片，使其提前冷却碎裂，探光随之消散。"
      ],
      "socialConsequences": "河谷乡约常请人用此术查看公共水槽或谷仓地面的近期污痕，以调解谁家牲畜弄脏了共用场地。城中公会则用于检查货栈地台是否被近期搬运弄脏，但若用来窥探他人住宅内墙，便会被视为侵犯隐私。港务人员会用它查看甲板上的油渍来源，但船主若发现有人未经同意施术，可要求对方说明目的。",
      "law": {
        "river": "public",
        "city": "public",
        "port": "public"
      },
      "proficiencyEffects": [
        "初学时探光只覆盖巴掌大的区域，污痕轮廓断断续续。",
        "熟练后能一次扫过整张桌面，暗色轮廓清晰可辨。",
        "精准控制下可只照出油渍而忽略水痕，减少误读。",
        "极高熟练度能稳定维持探光，仍不显示污痕来源或时间。"
      ]
    },
    {
      "id": "spell_light_11",
      "theory": "折光衣将魔力注入树脂，使其在目标衣物表面形成一层微弯的光膜。光膜并不隐形，而是把目标轮廓的光线折向两侧，使旁人的视线略微滑开。快速移动或雨水冲刷会打乱光膜的弯折方向，效果随之减弱。它只作用于一人，且不能改变声音、气味或影子。",
      "casting": "把树脂块贴在目标衣领内侧，用指尖沿衣缝画三道短竖线，每画一道轻弹一下树脂。画完后退开两步，确认光膜没有偏向一侧。",
      "failure": "树脂贴歪时，光膜会集中在一侧肩膀，使目标看起来像扛着一块扭曲的亮斑。雨水会令光膜出现裂缝，目标轮廓反而比平时更显眼，且树脂会黏在衣料上留下油点。",
      "counters": [
        "向目标泼水或等一场雨，光膜裂缝后轮廓恢复清晰。",
        "用强光从侧面直照，折光方向被冲乱，光膜失去作用。"
      ],
      "socialConsequences": "琥珀海岸的渔民有时请人给夜间收网的同伴施术，以免被岸上闲人认出而招来借贷纠纷。城中公会对此术态度谨慎，若用于逃避税吏或港务查验，会被追究责任。河谷乡约允许在节庆游行中用来增加趣味，但若有人借此混入他人宅院，则按侵入隐私处理。",
      "law": {
        "river": "public",
        "city": "public",
        "port": "public"
      },
      "proficiencyEffects": [
        "初学时光膜只遮住胸口，四肢轮廓仍然清楚。",
        "熟练后能覆盖全身，但快速跑动时边缘会闪烁。",
        "精准控制下雨水冲刷后仍能维持片刻，减少暴露。",
        "极高熟练度可让光膜均匀贴合，仍不能消除声音或影子。"
      ]
    },
    {
      "id": "spell_light_12",
      "theory": "破雾光让树脂在燃烧时放出一种穿透力较强的冷光，这种光在薄雾中散射较少，因而能提高可见距离。浓雾中水珠密集，光仍会被大量挡回，所以作用有限。它只照亮施术者前方一片扇形区域，不驱散雾气，也不改变雾的浓度。",
      "casting": "将树脂捏成小团，放在掌心吹一口气使其微微发亮，然后举到眼前，用拇指与食指圈成圆孔，从孔中望向雾中。保持圆孔稳定，直到冷光铺开。",
      "failure": "树脂受潮时冷光会断断续续，像远处闪电一样忽明忽暗，反而让眼睛更难适应。若圆孔太大，光会散成一片白幕，施术者只能看见自己的手指，雾中景物完全消失。",
      "counters": [
        "升起更浓的烟或雾，水珠密度增加后冷光被挡回。",
        "用不透光的厚布从侧面遮住树脂，扇形光域被切断。"
      ],
      "socialConsequences": "河谷渡船在晨雾中常请人施此术辨认对岸标桩，乡约认可这种公用。城中公会提醒成员，在码头货栈区使用时应避免直照他人窗户，否则可能被投诉窥视。港务规定，若因破雾光误导而撞上他船，施术者与船主须共同说明航行经过，货损按实际责任分摊。",
      "law": {
        "river": "public",
        "city": "public",
        "port": "public"
      },
      "proficiencyEffects": [
        "初学时扇形光域很窄，只能看清几步内的雾中轮廓。",
        "熟练后光域扩至正常范围，薄雾中可辨认绳索与桩头。",
        "精准控制下冷光不再刺眼，旁人眼睛较少感到不适。",
        "极高熟练度能稳定维持光域，浓雾中仍只增加有限距离。"
      ]
    }
  ]
}
